import React, { Suspense, useEffect, useState, useRef } from "react";
import { Canvas } from "@react-three/fiber";
import { OrbitControls, useGLTF, Environment } from "@react-three/drei";
import "../styles/Model.css";

const basePath = `${process.env.PUBLIC_URL}/noa`;

const modelData = [
  { path: `${basePath}/noa_v2.gltf`, label: "NOA – Basic" },
  { path: `${basePath}/resblend.gltf`, label: "NOA – Chef" },
  { path: `${basePath}/resblend1.gltf`, label: "NOA – Offemployee" },
];

// 사전 로드
modelData.forEach(({ path }) => useGLTF.preload(path));

function Model({ path }) {
  const gltf = useGLTF(path, true); // true는 draco 압축 X일 경우 안전
  return <primitive object={gltf.scene} scale={0.4} position={[0, 0.25, 0]} />;
}

export default function MyModelViewer({ isHovered, setIsHovered }) {
  const [isReady, setIsReady] = useState(false);
  const [modelIndex, setModelIndex] = useState(0);
  const controlsRef = useRef();

  useEffect(() => {
    const timeout = setTimeout(() => setIsReady(true), 100);
    return () => clearTimeout(timeout);
  }, []);

  useEffect(() => {
    if (controlsRef.current) {
      controlsRef.current.reset();
    }
  }, [modelIndex]);

  const handlePrev = () => {
    setModelIndex((prev) => (prev - 1 + modelData.length) % modelData.length);
  };

  const handleNext = () => {
    setModelIndex((prev) => (prev + 1) % modelData.length);
  };

  const currentModel = modelData[modelIndex];

  return (
    <div className="model-section" style={{ width: "100%", height: "100vh" }}>
      <div
        className="model-view"
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
        style={{ width: "500px", height: "500px" }}
      >
        {isReady && (
          <Canvas camera={{ position: [0, 1.5, 5.5], fov: 30 }} frameloop="always">
            <Suspense fallback={null}>
              <ambientLight intensity={1.2} />
              <directionalLight position={[3, 5, 2]} intensity={1.5} />
              <Environment preset="sunset" background={false} />
              <Model path={currentModel.path} />
              <OrbitControls
                ref={controlsRef}
                autoRotate={!isHovered}
                autoRotateSpeed={1.5}
                enableZoom={false}
                enablePan={false}
                enableRotate={false}
                target={[0, 0, 0]}
              />
            </Suspense>
          </Canvas>
        )}
      </div>

      <div className="label-row">
        <button className="nav-button" onClick={handlePrev}>←</button>
        <div className="model-label">{currentModel.label}</div>
        <button className="nav-button" onClick={handleNext}>→</button>
      </div>
    </div>
  );
}
